-- Default neovim config, stowed from ~/dotfiles/nvim by GNU Stow.
--
-- Dark / Dank Material Shell (dankshell) integration:
-- `colors/dms.lua` and `lua/lualine/themes/dms.lua` are generated by the
-- matugen templates shipped with the DMS integration of base46
-- (duxlabs-dev/base46). They produce a `dms` colorscheme that stays in
-- lockstep with the DMS theme (hot-reloads on wallpaper / light-dark change).

local opt = vim.opt

opt.undofile = true
opt.undodir = vim.fs.joinpath(vim.fn.stdpath("config"), "undodir")
opt.expandtab = true
opt.tabstop = 4
opt.shiftwidth = 4
opt.softtabstop = 4
opt.smartindent = true
opt.termguicolors = true
opt.number = true
opt.relativenumber = true
opt.cursorline = true
opt.signcolumn = "yes"
opt.scrolloff = 8
opt.wrap = false
opt.ignorecase = true
opt.smartcase = true
opt.splitright = true
opt.splitbelow = true
-- opt.clipboard = "unnamedplus"
opt.mouse = "a"
opt.confirm = true
opt.updatetime = 250
opt.timeoutlen = 400
opt.list = true
opt.listchars = { tab = "> ", trail = "·", nbsp = "␣" }

-- Native plugin manager.
vim.pack.add({
	{
		-- https://github.com/duxlabs-dev/base46 — NvChad's base46 theme
		-- plugin, standalone. Provides the `dms` colorscheme integration
		-- with Dank Material Shell.
		src = "https://github.com/duxlabs-dev/base46",
		name = "base46",
	},
	{
		src = "https://github.com/nvim-treesitter/nvim-treesitter",
		name = "nvim-treesitter",
		version = "main",
	},
	{
		-- Statusline, themed with the generated DMS lualine theme.
		src = "https://github.com/nvim-lualine/lualine.nvim",
		name = "lualine",
	},
})

-- base46 must be set up before any of its colorschemes can load.
require("base46").setup({})

-- nvim-treesitter (main branch): install/compile parsers when the plugin is
-- installed or updated, then enable highlighting per filetype.
vim.api.nvim_create_autocmd("PackChanged", {
	callback = function(event)
		if event.data.kind == "install" or event.data.kind == "update" then
			pcall(function()
				require("nvim-treesitter.install").update()
				require("nvim-treesitter").install({
					"bash",
					"c",
					"cpp",
					"json",
					"lua",
					"markdown",
					"markdown_inline",
					"python",
					"query",
					"vim",
					"vimdoc",
					"yaml",
				})
			end)
		end
	end,
})
vim.api.nvim_create_autocmd("FileType", {
	callback = function(args)
		pcall(vim.treesitter.start, args.buf)
	end,
})

-- DMS / dankshell colorscheme. `colors/dms.lua` handles reading DMS settings,
-- light/dark mode and its own hot-reload watchers; it needs base46 (above).
vim.cmd.colorscheme("dms")

-- Leader keys.
vim.g.mapleader = " "
vim.g.maplocalleader = " "

-- Transparency -------------------------------------------------------------
-- Make the editor background transparent so the DMS/terminal wallpaper shows
-- through. Statusline and float windows stay opaque. The ColorScheme hook
-- re-applies it, including DMS hot-reloads (which re-run `colorscheme dms`).

_G.dms_transparency_enabled = true

local function apply_transparency()
	local groups = { "Normal", "NormalNC" }
	for _, name in ipairs(groups) do
		local hl = vim.api.nvim_get_hl(0, { name = name, link = false })
		hl.bg = nil
		hl.background = nil
		vim.api.nvim_set_hl(0, name, hl)
	end
end

function _G.toggle_dms_transparency()
	_G.dms_transparency_enabled = not _G.dms_transparency_enabled
	-- Reset everything to the theme's opaque definition, then re-apply.
	vim.cmd.colorscheme("dms")
	if _G.dms_transparency_enabled then
		apply_transparency()
	end
	vim.notify(
		"Transparency " .. (_G.dms_transparency_enabled and "enabled" or "disabled"),
		vim.log.levels.INFO,
		{ title = "dms integration" }
	)
end

vim.api.nvim_create_autocmd("ColorScheme", {
	callback = function(args)
		if _G.dms_transparency_enabled and args.match == "dms" then
			apply_transparency()
		end
	end,
})
apply_transparency() -- apply on the initial colorscheme load

vim.keymap.set("n", "<leader>td", _G.toggle_dms_transparency, { desc = "Toggle transparent background" })

-- Statusline with the DMS-matugen generated lualine theme.
require("lualine").setup({
	options = {
		theme = require("lualine.themes.dms"),
		icons_enabled = true,
		globalstatus = true,
	},
	sections = {
		lualine_c = { { "filename", path = 1 } },
	},
})
